def rule_principal_executive_offices_zip(doc: dict) -> list[dict]:
    try:
        import re

        lines = doc.get("lines") or []
        if not isinstance(lines, list) or not lines:
            return []

        def _norm(value: object) -> str:
            return " ".join(str(value or "").split())

        def _is_nonempty(idx: int) -> bool:
            return bool(_norm(lines[idx].get("text")))

        def _same_page(a: int, b: int) -> bool:
            return lines[a].get("page_no") == lines[b].get("page_no")

        def _looks_like_address_fragment(text: str) -> bool:
            lowered = text.lower()
            if not text:
                return False
            if any(
                needle in lowered
                for needle in (
                    "registrant",
                    "telephone",
                    "employer identification",
                    "incorporation",
                    "principal executive offices",
                    "commission file",
                    "table of contents",
                    "exact name of registrant",
                    "state or other jurisdiction",
                )
            ):
                return False
            if re.search(
                r"\b(street|st\.|road|rd\.|avenue|ave\.|boulevard|blvd\.|drive|dr\.|parkway|pkwy\.|highway|hwy\.|lane|ln\.|court|ct\.|circle|cir\.|suite|ste\.|way|plaza|center|centre|place|po box|p\.o\.)\b",
                text,
                re.I,
            ):
                return True
            if re.search(r"\d", text):
                return True
            if "," in text and re.search(r"[A-Za-z]", text):
                return True
            return False

        needle = re.compile(r"principal executive offices?|address of principal executive offices?", re.I)
        candidate_indices = [
            idx
            for idx, line in enumerate(lines)
            if needle.search(_norm(line.get("text")))
        ]

        if not candidate_indices:
            return []

        # Prefer the earliest cover-page hit. These disclosures almost always place
        # the principal office address on the first page, near the beginning.
        candidate = min(candidate_indices, key=lambda idx: (lines[idx].get("page_no", 10**9), lines[idx].get("line_no", 10**9)))

        picked: list[int] = [candidate]
        prev = candidate - 1
        while prev >= 0 and len(picked) < 5:
            if not _same_page(prev, candidate):
                break
            prev_text = _norm(lines[prev].get("text"))
            if not prev_text:
                prev -= 1
                continue
            if _looks_like_address_fragment(prev_text):
                picked.insert(0, prev)
                prev -= 1
                continue
            break

        block = [_norm(lines[idx].get("text")) for idx in picked if _norm(lines[idx].get("text"))]
        block_text = "\n".join(block)

        # If the label line is isolated, pull in a short forward window as a fallback.
        if not re.search(r"\d", block_text):
            forward = candidate
            added = 0
            while forward + 1 < len(lines) and added < 2:
                nxt = forward + 1
                if not _same_page(nxt, candidate):
                    break
                if not _is_nonempty(nxt):
                    break
                forward = nxt
                added += 1
            if forward != candidate:
                if forward > candidate:
                    for idx in range(candidate + 1, forward + 1):
                        txt = _norm(lines[idx].get("text"))
                        if txt:
                            block.append(txt)
                block_text = "\n".join(block)

        if not block_text:
            return []

        start = picked[0]
        end = picked[-1]
        if len(block) > 0 and picked[-1] != candidate:
            end = picked[-1]
        if re.search(r"\d", block_text):
            span = {
                "text": block_text,
                "page_no": lines[start].get("page_no"),
                "line_no": lines[start].get("line_no"),
                "line_no_end": lines[end].get("line_no"),
            }
            return [span]

        block = [_norm(lines[idx].get("text")) for idx in picked if _norm(lines[idx].get("text"))]
            block_text = "\n".join(block)

        if not block_text:
            return []

        return [
            {
                "text": block_text,
                "page_no": lines[start].get("page_no"),
                "line_no": lines[start].get("line_no"),
                "line_no_end": lines[end].get("line_no"),
            }
        ]
    except Exception:
        return []

